package android.content; import java.util.*;
public class ContentValues { private final LinkedHashMap<String,Object> values=new LinkedHashMap<>(); public ContentValues(){} public ContentValues(ContentValues other){values.putAll(other.values);} public void put(String k,String v){values.put(k,v);} public void put(String k,Integer v){values.put(k,v);} public void put(String k,Long v){values.put(k,v);} public void put(String k,Boolean v){values.put(k,v);} public void put(String k,byte[] v){values.put(k,v);} public void putNull(String k){values.put(k,null);} public Object get(String k){return values.get(k);} public String getAsString(String k){Object v=get(k);return v==null?null:String.valueOf(v);} public Long getAsLong(String k){Object v=get(k);return v==null?null:(v instanceof Number?((Number)v).longValue():Long.valueOf(String.valueOf(v)));} public Set<Map.Entry<String,Object>> valueSet(){return values.entrySet();} public boolean containsKey(String k){return values.containsKey(k);} public int size(){return values.size();} }
